/* a game by its id — or by one of its aliases (Haunted Maze is maze.js, and
   an old link or badge may say 'maze'): always the one entry, so links,
   bests and badges all land on the canonical id */
export const arcadeById = id => (typeof id === 'string' && id
  ? ARCADE.find(g => g.id === id) || ARCADE.find(g => g.aliases?.includes(id)) || null
  : null);
export default ARCADE;
